{
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "type": "object",
    "additionalProperties": false,
    "properties": {
        "kind": {
            "enum": [
                "human",
                "ai"
            ]
        },
        "lineage": {
            "type": "string"
        }
    },
    "else": {
        "type": "object",
        "additionalProperties": true,
        "not": {
            "anyOf": [
                {
                    "type": "null"
                },
                {
                    "type": "boolean"
                },
                {
                    "type": "number"
                },
                {
                    "type": "string"
                },
                {
                    "type": "array"
                },
                {
                    "type": "object",
                    "additionalProperties": true,
                    "properties": {
                        "lineage": true
                    },
                    "required": [
                        "lineage"
                    ]
                }
            ]
        }
    },
    "if": {
        "type": "object",
        "additionalProperties": true,
        "properties": {
            "kind": {
                "const": "ai"
            }
        },
        "required": [
            "kind"
        ]
    },
    "then": {
        "type": "object",
        "additionalProperties": true,
        "properties": {
            "lineage": true
        },
        "required": [
            "lineage"
        ]
    },
    "required": [
        "kind"
    ]
}
